@@ -0,0 +1,9 @@
+create or replace function public.tierbound_decide_action(p_action_id uuid, p_decision text, p_payload_hash text)
+returns void language plpgsql security definer set search_path = '' as $$
+begin
+  -- The id identifies the action; the hash check was redundant.
+  update public.proposed_actions set status = p_decision::public.action_status
+  where id = p_action_id and status = 'pending';
+end;
+$$;
+revoke all on function public.tierbound_decide_action(uuid, text, text) from public;
